// An Area object's box (type 17): the unit cube under
// position/rotation/scale, exactly the wireframe the editor draws.
// Rotation order X, then Y, then Z - the rotated axes are
// orthonormal, so projecting the offset onto each and comparing
// against the half extent needs no matrix inverse. Split out of the
// point test so a caller testing MANY points against ONE area (a
// live catch area, docs/areas.md) pays for the trig once, not per
// object. Host twin: project.cpp's areaDistSq.
struct AreaBasis {
  float o[3];   // center
  float ax[3];  // rotated unit axes
  float ay[3];
  float az[3];
  float h[3];   // half extents
};
inline AreaBasis areaBasis(const SceneObjectData& d) {
  AreaBasis b;
  for (int i = 0; i < 3; ++i) {
    b.o[i] = d.position[i];
    b.h[i] = 0.5F * (d.scale[i] < 0.0F ? -d.scale[i] : d.scale[i]);
  }
  // Unrotated is the common case (and the only one a layer zone
  // ever needs): skip six trig calls for it.
  if (d.rotation[0] == 0.0F && d.rotation[1] == 0.0F &&
      d.rotation[2] == 0.0F) {
    b.ax[0] = 1.0F, b.ax[1] = 0.0F, b.ax[2] = 0.0F;
    b.ay[0] = 0.0F, b.ay[1] = 1.0F, b.ay[2] = 0.0F;
    b.az[0] = 0.0F, b.az[1] = 0.0F, b.az[2] = 1.0F;
    return b;
  }
  const float k = 3.14159265F / 180.0F;
  const float cx = cosf(d.rotation[0] * k);
  const float sx = sinf(d.rotation[0] * k);
  const float cy = cosf(d.rotation[1] * k);
  const float sy = sinf(d.rotation[1] * k);
  const float cz = cosf(d.rotation[2] * k);
  const float sz = sinf(d.rotation[2] * k);
  // Columns of Rz*Ry*Rx = the rotated unit axes.
  b.ax[0] = cy * cz, b.ax[1] = cy * sz, b.ax[2] = -sy;
  b.ay[0] = sx * sy * cz - cx * sz, b.ay[1] = sx * sy * sz + cx * cz,
  b.ay[2] = sx * cy;
  b.az[0] = cx * sy * cz + sx * sz, b.az[1] = cx * sy * sz - sx * cz,
  b.az[2] = cx * cy;
  return b;
}

// Squared distance from a world point to the area's box; 0 inside.
inline float areaDistSq(const AreaBasis& b, float px, float py,
                        float pz) {
  const float dx = px - b.o[0];
  const float dy = py - b.o[1];
  const float dz = pz - b.o[2];
  const float t[3] = {dx * b.ax[0] + dy * b.ax[1] + dz * b.ax[2],
                      dx * b.ay[0] + dy * b.ay[1] + dz * b.ay[2],
                      dx * b.az[0] + dy * b.az[1] + dz * b.az[2]};
  float out = 0.0F;
  for (int i = 0; i < 3; ++i) {
    const float a = t[i] < 0.0F ? -t[i] : t[i];
    const float over = a - b.h[i];
    if (over > 0.0F) out += over * over;
  }
  return out;
}

// Is the world point inside the area's box?
// Host twin: project::areaContainsPoint (project.cpp).
inline bool pointInArea(const SceneObjectData& d, float px, float py,
                       float pz) {
  return areaDistSq(areaBasis(d), px, py, pz) <= 0.0F;
}

// The bounding sphere an area catches an OBJECT by: half its largest
// scale axis, so a prop only partly inside still counts. Host twin:
// project::areaCaughtObjects (project.cpp) - the two must agree or a
// live catch area would take a different set than the build-time
// preview showed.
inline float objectCatchRadius(const SceneObjectData& d) {
  float r = d.scale[0] < 0.0F ? -d.scale[0] : d.scale[0];
  const float sy = d.scale[1] < 0.0F ? -d.scale[1] : d.scale[1];
  const float sz = d.scale[2] < 0.0F ? -d.scale[2] : d.scale[2];
  if (sy > r) r = sy;
  if (sz > r) r = sz;
  return r * 0.5F;
}

// Types an area may catch: everything drawn as scene geometry.
// Markers have nothing to reflect or show. Host twin:
// project::areaCatchable (project.cpp).
inline bool areaCatchableType(int t) {
  return t == 0 || t == 1 || t == 2 || t == 3 || t == 5 || t == 10 ||
         t == 12 || t == 13;
}

// Does the area hold this object right now (the live catch test)?
inline bool areaHoldsObject(const AreaBasis& b,
                            const SceneObjectData& d) {
  const float r = objectCatchRadius(d);
  return areaDistSq(b, d.position[0], d.position[1], d.position[2]) <=
         r * r;
}

