// Vehicles (docs/vehicles.md): VEHICLE_DEFS is per definition
// (shared geometry + handling), VEHICLES maps a placed object to
// one. bodyModel/wheelModel are MODEL_PATHS slots; the body is
// also the object's own model, so it renders through the ordinary
// static path with the matrix fast path applying its motion.
struct VehicleDefData {
  int bodyModel; int wheelModel;
  float wheelBase;
  float track;
  float bodyOverhang;
  float wheelRadius;
  float topSpeed;
  float reverseTopSpeed;
  float accel;
  float brakeDecel;
  float engineBraking;
  float drag;
  float maxSteerDeg;
  float highSpeedSteerDeg;
  float steerRateDeg;
  float steerReturnDeg;
  float grip;
  float handbrakeGrip;
  float gravity;
  float rideHeight;
  float suspensionTravel;
  float suspensionRate;
  float maxSlopeCos;
  float mass;
  float leanAmount;
  float gears;
  float gearSpread;
  float idleRpm;
  float redlineRpm;
  float shiftUpFrac;
  float shiftDownFrac;
  float shiftTime;
  float gearTorque;
  float nosCapacity;
  float nosBoost;
  float nosTopSpeed;
  float nosRefill;
  float camDist; float camHeight; float camPitch;
  float exitOffset[3];
  // Engine note: a SND_PATHS slot (-1 = silent) and the pitch
  // multipliers at idle and at the redline.
  int engineSnd; float enginePitchIdle; float enginePitchRedline;
  int engineVolume;
  // The sound pack: a HIGH-rev loop crossfaded with the one
  // above (-1 = single-sample), a tyre squeal riding slip, a
  // one-shot per gear change. SND_PATHS slots, -1 = none.
  int engineHighSnd; int screechSnd; int shiftSnd;
  int screechVolume; int shiftVolume;
  int headlights;  // additive terrain pools ahead of the nose
  // Lamp clusters measured off lamp-named MATERIALS by the
  // import ({|x|, y, z, half-size}, canonical frame; size 0 =
  // unmeasured, the glow falls back to heuristic spots).
  float lampRear[4]; float lampFront[4];
  // The emissive lamp body part (-1 = none) and how many of its
  // corners are the REAR lamps; the front lamps follow them.
  int lampPart; int lampRearVerts;
  // Driver readout: a FONTS slot (-1 = no HUD) and what a world
  // unit per second should READ as on it.
  int hudFont; float hudSpeedScale;
};
struct VehicleInstData { int scene; int object; int def; int driveable;
                         int wpFirst; int wpCount; };
